# Fallback embedded HTML dashboard for zero-config serverless deployments
DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>LMPC SmartInspector • Legal Metrology Compliance Checking System</title>\n    <!-- Tailwind CSS -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <!-- FontAwesome Icons -->\n    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n    <!-- Tesseract.js for robust client-side OCR without server bloat -->\n    <script src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js"></script>\n    <style>\n        @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap\');\n        body { font-family: \'Inter\', sans-serif; }\n        .bg-govt { background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 100%); }\n        .badge-pulse { animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }\n        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .6; } }\n    </style>\n</head>\n<body class="bg-slate-50 text-slate-800 min-h-screen flex flex-col">\n\n    <!-- Top Gov Navigation Bar -->\n    <header class="bg-govt text-white shadow-lg border-b border-blue-900/50 sticky top-0 z-50">\n        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n            <div class="flex justify-between items-center h-16">\n                <div class="flex items-center space-x-4">\n                    <div class="bg-white/10 p-2 rounded-lg border border-white/20 flex items-center justify-center">\n                        <i class="fa-solid fa-scale-balanced text-amber-400 text-2xl"></i>\n                    </div>\n                    <div>\n                        <div class="flex items-center space-x-2">\n                            <span class="text-xs tracking-wider uppercase text-amber-300 font-semibold">Government of India • Ministry of Consumer Affairs</span>\n                        </div>\n                        <h1 class="text-lg font-bold tracking-tight text-white flex items-center gap-2">\n                            LMPC SmartInspector\n                            <span class="text-xs font-medium px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">Rules 2011 & Amendments</span>\n                        </h1>\n                    </div>\n                </div>\n                \n                <div class="flex items-center space-x-4 text-xs">\n                    <div class="hidden md:flex items-center space-x-2 bg-slate-800/80 px-3 py-1.5 rounded-lg border border-slate-700">\n                        <span class="w-2 h-2 rounded-full bg-emerald-400 badge-pulse"></span>\n                        <span class="text-slate-300">Rule Engine: <strong class="text-white">G.S.R. 202(E) | 779(E) | 577(E)</strong></span>\n                    </div>\n                    <div class="text-right">\n                        <p class="text-slate-300">Enforcement Officer</p>\n                        <p class="font-bold text-amber-300">Central Metrology Cell</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </header>\n\n    <main class="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">\n\n        <!-- Top Metrics Bar -->\n        <div class="grid grid-cols-2 md:grid-cols-4 gap-4" id="metricsBar">\n            <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                <p class="text-xs text-slate-500 font-medium uppercase tracking-wider">Total Inspected Packages</p>\n                <p class="text-2xl font-bold text-slate-900 mt-1" id="statTotal">--</p>\n            </div>\n            <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                <p class="text-xs text-emerald-600 font-medium uppercase tracking-wider">Compliant Products</p>\n                <p class="text-2xl font-bold text-emerald-700 mt-1" id="statCompliant">--</p>\n            </div>\n            <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                <p class="text-xs text-rose-600 font-medium uppercase tracking-wider">Violations Detected</p>\n                <p class="text-2xl font-bold text-rose-700 mt-1" id="statViolations">--</p>\n            </div>\n            <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                <p class="text-xs text-blue-600 font-medium uppercase tracking-wider">Compliance Pass Rate</p>\n                <p class="text-2xl font-bold text-blue-700 mt-1" id="statRate">--%</p>\n            </div>\n        </div>\n\n        <!-- 1-Click Live Test Scenarios Banner -->\n        <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n            <div class="flex items-center justify-between mb-3">\n                <h3 class="text-sm font-bold text-slate-800 flex items-center gap-2">\n                    <i class="fa-solid fa-bolt text-amber-500"></i>\n                    1-Click Live Demonstration Scenarios\n                </h3>\n                <span class="text-xs text-slate-500">Pre-configured test packages for instant live inspection</span>\n            </div>\n            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-2.5">\n                <button onclick="loadDemoSample(\'sample_01\')" class="demo-btn text-left p-2.5 rounded-lg border border-slate-200 hover:border-emerald-500 hover:bg-emerald-50/50 transition group">\n                    <div class="flex items-center justify-between">\n                        <span class="text-xs font-semibold text-slate-900 group-hover:text-emerald-700">1. Compliant Pack</span>\n                        <span class="text-[10px] bg-emerald-100 text-emerald-800 px-1.5 py-0.5 rounded font-bold">100% Pass</span>\n                    </div>\n                    <p class="text-[11px] text-slate-500 mt-1 truncate">NutriBite Wheat Biscuits (250g)</p>\n                </button>\n\n                <button onclick="loadDemoSample(\'sample_02\')" class="demo-btn text-left p-2.5 rounded-lg border border-slate-200 hover:border-rose-500 hover:bg-rose-50/50 transition group">\n                    <div class="flex items-center justify-between">\n                        <span class="text-xs font-semibold text-slate-900 group-hover:text-rose-700">2. Illegal \'gms\' Unit</span>\n                        <span class="text-[10px] bg-rose-100 text-rose-800 px-1.5 py-0.5 rounded font-bold">Rule 13 Flag</span>\n                    </div>\n                    <p class="text-[11px] text-slate-500 mt-1 truncate">Desi Swad Namkeen (400 gms)</p>\n                </button>\n\n                <button onclick="loadDemoSample(\'sample_03\')" class="demo-btn text-left p-2.5 rounded-lg border border-slate-200 hover:border-rose-500 hover:bg-rose-50/50 transition group">\n                    <div class="flex items-center justify-between">\n                        <span class="text-xs font-semibold text-slate-900 group-hover:text-rose-700">3. Missing USP</span>\n                        <span class="text-[10px] bg-rose-100 text-rose-800 px-1.5 py-0.5 rounded font-bold">Rule 6(11)</span>\n                    </div>\n                    <p class="text-[11px] text-slate-500 mt-1 truncate">AquaPure Mineral Water (1L)</p>\n                </button>\n\n                <button onclick="loadDemoSample(\'sample_04\')" class="demo-btn text-left p-2.5 rounded-lg border border-slate-200 hover:border-rose-500 hover:bg-rose-50/50 transition group">\n                    <div class="flex items-center justify-between">\n                        <span class="text-xs font-semibold text-slate-900 group-hover:text-rose-700">4. Future Mfg Date</span>\n                        <span class="text-[10px] bg-rose-100 text-rose-800 px-1.5 py-0.5 rounded font-bold">Date Fraud</span>\n                    </div>\n                    <p class="text-[11px] text-slate-500 mt-1 truncate">FarmFresh Cow Ghee (12/2026)</p>\n                </button>\n\n                <button onclick="loadDemoSample(\'sample_05\')" class="demo-btn text-left p-2.5 rounded-lg border border-slate-200 hover:border-blue-500 hover:bg-blue-50/50 transition group">\n                    <div class="flex items-center justify-between">\n                        <span class="text-xs font-semibold text-slate-900 group-hover:text-blue-700">5. Electronics QR</span>\n                        <span class="text-[10px] bg-blue-100 text-blue-800 px-1.5 py-0.5 rounded font-bold">GSR 577(E)</span>\n                    </div>\n                    <p class="text-[11px] text-slate-500 mt-1 truncate">SoundMax Wireless Earbuds</p>\n                </button>\n            </div>\n        </div>\n\n        <!-- Main Scanning Studio & Workbench -->\n        <div class="grid grid-cols-1 lg:grid-cols-12 gap-6">\n\n            <!-- Left: Image Upload & Visual Bounding Box Inspector (5 Cols) -->\n            <div class="lg:col-span-5 space-y-4">\n                <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                    <div class="flex items-center justify-between mb-3">\n                        <h2 class="text-sm font-bold text-slate-900 flex items-center gap-2">\n                            <i class="fa-solid fa-camera text-blue-600"></i>\n                            Package Label Visualizer\n                        </h2>\n                        <span class="text-xs text-slate-400" id="imageDimLabel">Waiting for scan</span>\n                    </div>\n\n                    <!-- Upload dropzone -->\n                    <div id="dropZone" class="border-2 border-dashed border-slate-300 hover:border-blue-500 bg-slate-50/50 rounded-lg p-4 text-center cursor-pointer transition relative">\n                        <input type="file" id="fileInput" accept="image/*" class="absolute inset-0 opacity-0 cursor-pointer w-full h-full">\n                        <i class="fa-solid fa-cloud-arrow-up text-3xl text-slate-400 mb-2"></i>\n                        <p class="text-xs font-semibold text-slate-700">Drag & drop package image, or <span class="text-blue-600">browse</span></p>\n                        <p class="text-[11px] text-slate-400 mt-1">Supports JPG, PNG, WEBP (FMCG, Food, Electronics labels)</p>\n                    </div>\n\n                    <!-- Image Display with Canvas Overlay -->\n                    <div id="imageViewerContainer" class="mt-4 bg-slate-950 rounded-xl overflow-hidden border border-slate-700 hidden p-3 flex items-center justify-center min-h-[420px]">\n                        <div class="relative inline-block max-w-full" id="imageCanvasWrapper">\n                            <img id="productImage" src="" alt="Product Label" class="max-h-[520px] max-w-full w-auto h-auto block rounded shadow-lg mx-auto">\n                            <canvas id="overlayCanvas" class="absolute top-0 left-0 w-full h-full pointer-events-none rounded"></canvas>\n                        </div>\n                    </div>\n\n                    <div id="bboxLegend" class="mt-3 flex flex-wrap gap-2 text-[11px] hidden">\n                        <span class="inline-flex items-center gap-1 bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded border border-emerald-200">\n                            <span class="w-2 h-2 rounded-full bg-emerald-500"></span> Verified Mandatory\n                        </span>\n                        <span class="inline-flex items-center gap-1 bg-rose-50 text-rose-700 px-2 py-0.5 rounded border border-rose-200">\n                            <span class="w-2 h-2 rounded-full bg-rose-500"></span> Statutory Infringement\n                        </span>\n                        <span class="inline-flex items-center gap-1 bg-blue-50 text-blue-700 px-2 py-0.5 rounded border border-blue-200">\n                            <span class="w-2 h-2 rounded-full bg-blue-500"></span> QR / Electronic\n                        </span>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Right: Real-time Compliance Scorecard & Rule Breakdown (7 Cols) -->\n            <div class="lg:col-span-7 space-y-4">\n\n                <!-- Compliance Verdict Banner -->\n                <div id="verdictBanner" class="bg-white p-5 rounded-xl shadow-sm border border-slate-200">\n                    <div class="flex items-center justify-between">\n                        <div class="flex items-center space-x-4">\n                            <div id="scoreCircle" class="w-16 h-16 rounded-full flex items-center justify-center font-extrabold text-xl text-white bg-slate-400">\n                                --%\n                            </div>\n                            <div>\n                                <span id="verdictBadge" class="text-xs uppercase font-bold tracking-wider px-2.5 py-1 rounded-full bg-slate-100 text-slate-600">\n                                    Awaiting Inspection\n                                </span>\n                                <h3 id="commodityTitle" class="text-base font-bold text-slate-900 mt-1">Select or Upload a Package</h3>\n                                <p id="inspectedAtText" class="text-xs text-slate-500">Legal Metrology Act, 2009 • Enforcement Module</p>\n                            </div>\n                        </div>\n\n                        <div class="text-right">\n                            <button id="downloadPdfBtn" disabled class="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white text-xs font-semibold px-4 py-2.5 rounded-lg shadow-sm transition flex items-center gap-2">\n                                <i class="fa-solid fa-file-pdf"></i>\n                                <span>Inspection Memo (PDF)</span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Violations List -->\n                <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                    <h3 class="text-sm font-bold text-slate-900 mb-3 flex items-center gap-2">\n                        <i class="fa-solid fa-triangle-exclamation text-amber-500"></i>\n                        Statutory Infringements & Rule Violations\n                        <span id="violationCountBadge" class="text-xs px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 font-bold">0</span>\n                    </h3>\n\n                    <div id="violationsContainer" class="space-y-2.5">\n                        <div class="p-6 text-center text-slate-400 text-xs">\n                            <i class="fa-solid fa-magnifying-glass text-2xl mb-2 text-slate-300 block"></i>\n                            Select a demo package from the top or upload an image to run automated compliance checks.\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Extracted Key-Value Declarations Table -->\n                <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n                    <h3 class="text-sm font-bold text-slate-900 mb-3 flex items-center gap-2">\n                        <i class="fa-solid fa-list-check text-indigo-600"></i>\n                        Extracted Statutory Declarations (Rule 6)\n                    </h3>\n                    <div class="overflow-x-auto">\n                        <table class="w-full text-left text-xs border-collapse">\n                            <thead>\n                                <tr class="border-b border-slate-200 text-slate-400 font-medium">\n                                    <th class="py-2 px-3">Declaration Field</th>\n                                    <th class="py-2 px-3">Extracted Value</th>\n                                    <th class="py-2 px-3">Rule Reference</th>\n                                    <th class="py-2 px-3">Status</th>\n                                </tr>\n                            </thead>\n                            <tbody id="extractedTableBody" class="divide-y divide-slate-100 text-slate-700">\n                                <tr>\n                                    <td colspan="4" class="py-4 text-center text-slate-400">No active scan loaded</td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- Bottom: Historical Scans & Repository Section -->\n        <div class="bg-white p-4 rounded-xl shadow-sm border border-slate-200">\n            <div class="flex items-center justify-between mb-4">\n                <div>\n                    <h3 class="text-sm font-bold text-slate-900 flex items-center gap-2">\n                        <i class="fa-solid fa-folder-open text-amber-600"></i>\n                        Legal Metrology Inspection Repository\n                    </h3>\n                    <p class="text-xs text-slate-500">Permanent audit log and case record repository under Legal Metrology Act, 2009</p>\n                </div>\n                <button onclick="loadHistory()" class="text-xs text-blue-600 hover:text-blue-800 font-medium flex items-center gap-1">\n                    <i class="fa-solid fa-arrows-rotate"></i> Refresh\n                </button>\n            </div>\n\n            <div class="overflow-x-auto">\n                <table class="w-full text-left text-xs border-collapse">\n                    <thead>\n                        <tr class="bg-slate-50 border-b border-slate-200 text-slate-500 font-semibold">\n                            <th class="py-2.5 px-3">Inspection UID</th>\n                            <th class="py-2.5 px-3">Commodity Name</th>\n                            <th class="py-2.5 px-3">Manufacturer</th>\n                            <th class="py-2.5 px-3">Net Qty</th>\n                            <th class="py-2.5 px-3">MRP / USP</th>\n                            <th class="py-2.5 px-3">Score</th>\n                            <th class="py-2.5 px-3">Status</th>\n                            <th class="py-2.5 px-3 text-right">Action</th>\n                        </tr>\n                    </thead>\n                    <tbody id="historyTableBody" class="divide-y divide-slate-100 text-slate-700">\n                        <tr>\n                            <td colspan="8" class="py-4 text-center text-slate-400">Loading audit history...</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n    </main>\n\n    <!-- Footer -->\n    <footer class="bg-slate-900 text-slate-400 text-xs py-4 border-t border-slate-800 mt-auto">\n        <div class="max-w-7xl mx-auto px-4 text-center flex flex-col sm:flex-row justify-between items-center gap-2">\n            <p>© 2026 Department of Consumer Affairs • Smart India Hackathon Prototype</p>\n            <p>Built strictly according to G.S.R. 202(E), G.S.R. 779(E) & G.S.R. 577(E)</p>\n        </div>\n    </footer>\n\n    <!-- Frontend Script -->\n    <script>\n        let currentScanId = null;\n\n        // Initialize metrics & history on load\n        window.addEventListener(\'DOMContentLoaded\', () => {\n            loadDashboardStats();\n            loadHistory();\n            // Automatically load sample 01 for a great first impression\n            loadDemoSample(\'sample_01\');\n        });\n\n        // Load 1-Click Demo Sample\n        async function loadDemoSample(sampleId) {\n            try {\n                showLoadingState();\n                const resp = await fetch(`/api/scan/demo/${sampleId}`, { method: \'POST\' });\n                if (!resp.ok) throw new Error(\'Failed scanning sample\');\n                const data = await resp.json();\n                renderScanResults(data);\n                loadDashboardStats();\n                loadHistory();\n            } catch (err) {\n                alert(\'Error loading sample: \' + err.message);\n            }\n        }\n\n        // Handle File Upload with Instant Client Preview\n        let currentBoxes = [];\n        const fileInput = document.getElementById(\'fileInput\');\n        fileInput.addEventListener(\'change\', async (e) => {\n            if (e.target.files.length === 0) return;\n            const file = e.target.files[0];\n            \n            // 1. Instant local preview so user sees their photo immediately\n            const reader = new FileReader();\n            const imgEl = document.getElementById(\'productImage\');\n            const imgContainer = document.getElementById(\'imageViewerContainer\');\n            const legend = document.getElementById(\'bboxLegend\');\n            \n            reader.onload = (ev) => {\n                imgEl.src = ev.target.result;\n                imgContainer.classList.remove(\'hidden\');\n                legend.classList.remove(\'hidden\');\n                // Clear any old bounding boxes while scanning\n                const canvas = document.getElementById(\'overlayCanvas\');\n                if (canvas) {\n                    const ctx = canvas.getContext(\'2d\');\n                    ctx.clearRect(0, 0, canvas.width, canvas.height);\n                }\n            };\n            reader.readAsDataURL(file);\n\n            // 2. Send to backend AI pipeline with client-side OCR extraction\n            const formData = new FormData();\n            formData.append(\'image\', file);\n\n            try {\n                showLoadingState(\'Extracting label declarations via Vision OCR...\');\n                \n                // If Tesseract.js is available, extract text segments and coordinates directly in browser\n                if (window.Tesseract) {\n                    try {\n                        const worker = await Tesseract.createWorker(\'eng\');\n                        const ocrRes = await worker.recognize(file);\n                        await worker.terminate();\n                        if (ocrRes && ocrRes.data && ocrRes.data.lines) {\n                            const ocrItems = [];\n                            ocrRes.data.lines.forEach(l => {\n                                const subLines = l.text.split(\'\\n\').map(s => s.trim()).filter(s => s.length > 0);\n                                subLines.forEach(sub => {\n                                    ocrItems.push({\n                                        text: sub,\n                                        box: [l.bbox.x0, l.bbox.y0, l.bbox.x1, l.bbox.y1],\n                                        conf: l.confidence\n                                    });\n                                });\n                            });\n                            if (ocrItems.length > 0) {\n                                formData.append(\'ocr_json\', JSON.stringify(ocrItems));\n                            }\n                        }\n                    } catch (ocrErr) {\n                        console.warn(\'Browser OCR notice (falling back to server analysis):\', ocrErr);\n                    }\n                }\n\n                showLoadingState(\'Evaluating Legal Metrology Statutory Rules...\');\n                const resp = await fetch(\'/api/scan/upload\', {\n                    method: \'POST\',\n                    body: formData\n                });\n                if (!resp.ok) throw new Error(\'Scan failed (HTTP \' + resp.status + \')\');\n                const data = await resp.json();\n                renderScanResults(data);\n                loadDashboardStats();\n                loadHistory();\n            } catch (err) {\n                alert(\'Error scanning uploaded image: \' + err.message);\n            }\n        });\n\n        function showLoadingState(msg) {\n            document.getElementById(\'commodityTitle\').innerText = msg || \'Scanning & Verifying Declarations...\';\n            document.getElementById(\'verdictBadge\').className = \'text-xs uppercase font-bold tracking-wider px-2.5 py-1 rounded-full bg-blue-100 text-blue-700\';\n            document.getElementById(\'verdictBadge\').innerText = \'Processing AI Pipeline\';\n        }\n\n        function renderScanResults(data) {\n            currentScanId = data.scan_id;\n            currentBoxes = data.bounding_boxes || [];\n            const extracted = data.extracted_data;\n            const result = data.compliance_result;\n\n            // 1. Update Image & Canvas\n            const imgEl = document.getElementById(\'productImage\');\n            const imgContainer = document.getElementById(\'imageViewerContainer\');\n            const legend = document.getElementById(\'bboxLegend\');\n            \n            imgEl.src = data.image_url;\n            imgContainer.classList.remove(\'hidden\');\n            legend.classList.remove(\'hidden\');\n\n            imgEl.onload = () => {\n                document.getElementById(\'imageDimLabel\').innerText = `${imgEl.naturalWidth} × ${imgEl.naturalHeight} px`;\n                drawBoundingBoxes(currentBoxes, imgEl);\n            };\n            if (imgEl.complete && imgEl.naturalWidth > 0) {\n                document.getElementById(\'imageDimLabel\').innerText = `${imgEl.naturalWidth} × ${imgEl.naturalHeight} px`;\n                drawBoundingBoxes(currentBoxes, imgEl);\n            }\n\n            // 2. Update Verdict Banner\n            const score = result.compliance_score;\n            const isCompliant = result.is_compliant;\n            const circle = document.getElementById(\'scoreCircle\');\n            const badge = document.getElementById(\'verdictBadge\');\n\n            circle.innerText = `${score}%`;\n            if (isCompliant) {\n                circle.className = \'w-16 h-16 rounded-full flex items-center justify-center font-extrabold text-xl text-white bg-emerald-600 shadow-md shadow-emerald-200\';\n                badge.className = \'text-xs uppercase font-bold tracking-wider px-2.5 py-1 rounded-full bg-emerald-100 text-emerald-800\';\n                badge.innerHTML = \'<i class="fa-solid fa-check mr-1"></i> COMPLIANT\';\n            } else {\n                circle.className = \'w-16 h-16 rounded-full flex items-center justify-center font-extrabold text-xl text-white bg-rose-600 shadow-md shadow-rose-200\';\n                badge.className = \'text-xs uppercase font-bold tracking-wider px-2.5 py-1 rounded-full bg-rose-100 text-rose-800\';\n                badge.innerHTML = \'<i class="fa-solid fa-triangle-exclamation mr-1"></i> NON-COMPLIANT • NOTICE ISSUED\';\n            }\n\n            document.getElementById(\'commodityTitle\').innerText = extracted.commodity_name || \'Packaged Commodity\';\n            document.getElementById(\'inspectedAtText\').innerText = `Inspected at ${result.inspected_at} • Ref: Section 36 of LM Act, 2009`;\n\n            // Enable PDF download\n            const pdfBtn = document.getElementById(\'downloadPdfBtn\');\n            pdfBtn.disabled = false;\n            pdfBtn.onclick = () => {\n                window.open(`/api/report/${currentScanId}`, \'_blank\');\n            };\n\n            // 3. Render Violations\n            const vContainer = document.getElementById(\'violationsContainer\');\n            const vBadge = document.getElementById(\'violationCountBadge\');\n            vBadge.innerText = result.violations.length;\n\n            if (result.violations.length === 0) {\n                vContainer.innerHTML = `\n                    <div class="p-4 bg-emerald-50 border border-emerald-200 rounded-lg text-emerald-800 text-xs flex items-center gap-3">\n                        <i class="fa-solid fa-circle-check text-emerald-600 text-xl"></i>\n                        <div>\n                            <p class="font-bold">Full Statutory Compliance Verified</p>\n                            <p class="text-emerald-700 mt-0.5">All mandatory declarations, font size thresholds, and Unit Sale Price calculations conform to Legal Metrology Rules, 2011.</p>\n                        </div>\n                    </div>\n                `;\n            } else {\n                vContainer.innerHTML = result.violations.map(v => {\n                    const isCrit = v.severity === \'CRITICAL\';\n                    const bg = isCrit ? \'bg-rose-50 border-rose-200\' : \'bg-amber-50 border-amber-200\';\n                    const textBadge = isCrit ? \'bg-rose-100 text-rose-800\' : \'bg-amber-100 text-amber-800\';\n                    return `\n                        <div class="p-3 ${bg} border rounded-lg text-xs space-y-1">\n                            <div class="flex items-center justify-between">\n                                <span class="font-bold text-slate-900 flex items-center gap-1.5">\n                                    <i class="fa-solid fa-circle-exclamation ${isCrit ? \'text-rose-600\' : \'text-amber-600\'}"></i>\n                                    ${v.title}\n                                </span>\n                                <span class="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded ${textBadge}">${v.severity}</span>\n                            </div>\n                            <p class="text-slate-600">${v.description}</p>\n                            <div class="text-[11px] text-slate-500 flex justify-between pt-1 border-t border-slate-200/50">\n                                <span>Ref: <strong>${v.rule_reference}</strong></span>\n                                <span class="text-rose-700 font-semibold">Penalty: ${v.statutory_penalty_ref}</span>\n                            </div>\n                        </div>\n                    `;\n                }).join(\'\');\n            }\n\n            // 4. Render Extracted Declarations Table\n            const tbody = document.getElementById(\'extractedTableBody\');\n            const hasUspMismatch = result.violations.some(v => v.rule_id === \'RULE_6_11_USP_MISMATCH\');\n            const hasInvertedExp = result.violations.some(v => v.rule_id === \'RULE_6_1_D_INVERTED_EXPIRY\');\n            const hasTaxMissing = result.violations.some(v => v.rule_id === \'RULE_6_1_E_TAX_CLAUSE\');\n\n            const fields = [\n                { label: \'Manufacturer / Packer\', val: (extracted.manufacturer_name ? extracted.manufacturer_name + (extracted.manufacturer_address ? `, ${extracted.manufacturer_address}` : \'\') : \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\'), rule: \'Rule 6(1)(a) & 10\', valid: !!extracted.manufacturer_name },\n                { label: \'Country of Origin\', val: extracted.country_of_origin || \'India\', rule: \'Rule 10(2)\', valid: !!extracted.country_of_origin },\n                { label: \'Common / Generic Name\', val: extracted.generic_name || \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\', rule: \'Rule 6(1)(b)\', valid: !!extracted.generic_name },\n                { label: \'Declared Net Quantity\', val: extracted.net_quantity_raw || \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\', rule: \'Rule 6(1)(c) & 13\', valid: !!extracted.net_quantity_value && extracted.net_quantity_unit !== \'gms\' },\n                { label: \'Batch / Lot Number\', val: extracted.batch_number || \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\', rule: \'Rule 6(1)(d)\', valid: !!extracted.batch_number },\n                { label: \'Maximum Retail Price (MRP)\', val: (extracted.mrp_raw ? extracted.mrp_raw + (hasTaxMissing ? \' <span class="text-amber-600 font-semibold">[Tax Clause Missing]</span>\' : \'\') : \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\'), rule: \'Rule 6(1)(e)\', valid: !!extracted.mrp_value && !hasTaxMissing },\n                { label: \'Unit Sale Price (USP)\', val: (extracted.unit_sale_price_raw ? extracted.unit_sale_price_raw + (hasUspMismatch ? \' <span class="text-rose-600 font-bold">[CALCULATION MISMATCH]</span>\' : \'\') : \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\'), rule: \'Rule 6(11) (2021 Amend)\', valid: !!extracted.unit_sale_price_value && !hasUspMismatch },\n                { label: \'Month & Year of Mfg\', val: extracted.mfg_date || \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\', rule: \'Rule 6(1)(d)\', valid: !!extracted.mfg_date },\n                { label: \'Expiry / Best Before Date\', val: (extracted.exp_date ? extracted.exp_date + (hasInvertedExp ? \' <span class="text-rose-600 font-bold">[INVALID: Precedes Mfg Date]</span>\' : \'\') : \'Not Declared\'), rule: \'Rule 6(1)(d)\', valid: !!extracted.exp_date && !hasInvertedExp },\n                { label: \'Consumer Care Cell\', val: `${extracted.consumer_care_phone || \'\'} ${extracted.consumer_care_email ? \'• \' + extracted.consumer_care_email : \'\'}`.trim() || \'<span class="text-rose-600 font-bold">NOT DECLARED</span>\', rule: \'Rule 6(2)\', valid: !!extracted.consumer_care_phone && !!extracted.consumer_care_email },\n                { label: \'Measured Numeral Height\', val: `${extracted.measured_numeral_height_mm || \'N/A\'} mm`, rule: \'Rule 7 & Sched II\', valid: (extracted.measured_numeral_height_mm || 0) >= 2.0 }\n            ];\n\n            tbody.innerHTML = fields.map(f => `\n                <tr class="hover:bg-slate-50 transition">\n                    <td class="py-2.5 px-3 font-semibold text-slate-900">${f.label}</td>\n                    <td class="py-2.5 px-3 text-slate-700">${f.val}</td>\n                    <td class="py-2.5 px-3 text-slate-500 font-mono text-[11px]">${f.rule}</td>\n                    <td class="py-2.5 px-3">\n                        ${f.valid \n                            ? \'<span class="text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded border border-emerald-200 font-medium">Valid</span>\' \n                            : \'<span class="text-rose-700 bg-rose-50 px-2 py-0.5 rounded border border-rose-200 font-bold">Non-Compliant</span>\'}\n                    </td>\n                </tr>\n            `).join(\'\');\n        }\n\n        // Draw Bounding Boxes on Overlay Canvas (Pixel-Perfect Natural Coordinate Mapping)\n        function drawBoundingBoxes(boxes, imgEl) {\n            const canvas = document.getElementById(\'overlayCanvas\');\n            if (!canvas || !imgEl || !imgEl.naturalWidth || !imgEl.naturalHeight) return;\n\n            // Set canvas internal resolution to match natural image dimensions\n            canvas.width = imgEl.naturalWidth;\n            canvas.height = imgEl.naturalHeight;\n\n            const ctx = canvas.getContext(\'2d\');\n            ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n            if (!boxes || boxes.length === 0) return;\n\n            boxes.forEach(b => {\n                const [x1, y1, x2, y2] = b.box;\n                const w = x2 - x1;\n                const h = y2 - y1;\n                const col = b.color || \'#3b82f6\';\n\n                // Bounding Box Stroke\n                const strokeW = Math.max(3, Math.round(canvas.width / 200));\n                ctx.lineWidth = strokeW;\n                ctx.strokeStyle = col;\n                ctx.strokeRect(x1, y1, w, h);\n\n                // Semi-transparent highlight fill\n                ctx.fillStyle = col + \'22\';\n                ctx.fillRect(x1, y1, w, h);\n\n                // Header tag banner\n                const tagH = Math.max(26, Math.round(canvas.height / 32));\n                const fontSz = Math.max(13, Math.round(tagH * 0.55));\n                ctx.fillStyle = col;\n                ctx.fillRect(x1, Math.max(0, y1 - tagH), Math.min(w, canvas.width * 0.7), tagH);\n\n                // Header text\n                ctx.fillStyle = \'#ffffff\';\n                ctx.font = `bold ${fontSz}px Inter, sans-serif`;\n                ctx.fillText(b.label, x1 + 6, Math.max(fontSz + 2, y1 - (tagH - fontSz) / 2));\n            });\n        }\n\n        // Re-align on window resize\n        window.addEventListener(\'resize\', () => {\n            const imgEl = document.getElementById(\'productImage\');\n            if (imgEl && imgEl.complete && currentBoxes.length > 0) {\n                drawBoundingBoxes(currentBoxes, imgEl);\n            }\n        });\n\n        // Load Global Dashboard Stats\n        async function loadDashboardStats() {\n            try {\n                const res = await fetch(\'/api/metrics\');\n                const data = await res.json();\n                document.getElementById(\'statTotal\').innerText = data.total_scanned;\n                document.getElementById(\'statCompliant\').innerText = data.compliant_count;\n                document.getElementById(\'statViolations\').innerText = data.non_compliant_count;\n                document.getElementById(\'statRate\').innerText = `${data.compliance_rate}%`;\n            } catch (err) {\n                console.error(err);\n            }\n        }\n\n        // Load History Table\n        async function loadHistory() {\n            try {\n                const res = await fetch(\'/api/history\');\n                const data = await res.json();\n                const tbody = document.getElementById(\'historyTableBody\');\n                if (data.length === 0) {\n                    tbody.innerHTML = \'<tr><td colspan="8" class="py-4 text-center text-slate-400">No inspections recorded yet</td></tr>\';\n                    return;\n                }\n                tbody.innerHTML = data.map(row => `\n                    <tr class="hover:bg-slate-50 transition cursor-pointer" onclick="viewHistoricalScan(${row.id})">\n                        <td class="py-2.5 px-3 font-mono font-bold text-blue-600">${row.scan_uid}</td>\n                        <td class="py-2.5 px-3 font-semibold text-slate-900">${row.commodity_name}</td>\n                        <td class="py-2.5 px-3 text-slate-600 truncate max-w-[150px]">${row.manufacturer_name}</td>\n                        <td class="py-2.5 px-3">${row.net_quantity}</td>\n                        <td class="py-2.5 px-3 font-mono">${row.mrp}</td>\n                        <td class="py-2.5 px-3 font-bold">${row.compliance_score}%</td>\n                        <td class="py-2.5 px-3">\n                            ${row.is_compliant \n                                ? \'<span class="text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded text-[10px] font-bold">COMPLIANT</span>\' \n                                : \'<span class="text-rose-700 bg-rose-50 px-2 py-0.5 rounded text-[10px] font-bold">NON-COMPLIANT</span>\'}\n                        </td>\n                        <td class="py-2.5 px-3 text-right">\n                            <a href="/api/report/${row.id}" target="_blank" onclick="event.stopPropagation()" class="text-blue-600 hover:text-blue-800 font-semibold inline-flex items-center gap-1">\n                                <i class="fa-solid fa-file-pdf"></i> Memo\n                            </a>\n                        </td>\n                    </tr>\n                `).join(\'\');\n            } catch (err) {\n                console.error(err);\n            }\n        }\n\n        // View single scan from history\n        async function viewHistoricalScan(id) {\n            try {\n                const res = await fetch(`/api/scan/${id}`);\n                const data = await res.json();\n                renderScanResults(data);\n                window.scrollTo({ top: 0, behavior: \'smooth\' });\n            } catch (err) {\n                alert(\'Failed retrieving scan: \' + err.message);\n            }\n        }\n    </script>\n</body>\n</html>\n'
